/** Pure browser export functions for the synthetic demo. Backend exports use the same public schemas. */
const enc=new TextEncoder();const json=v=>JSON.stringify(v);const xml=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
const protect=v=>typeof v==='string'&&/^[=+@-]/.test(v.trimStart())?"'"+v:v;
function csv(rows,fields,delimiter=','){const q=v=>'"'+String(protect(v)??'').replaceAll('"','""')+'"';return '\ufeff'+[fields.map(q).join(delimiter),...rows.map(r=>fields.map(k=>q(r[k])).join(delimiter))].join('\r\n');}
export function tokenize(text,spans){const chars=Array.from(text),out=[];let cp=0;for(const m of text.matchAll(/\S+/gu)){const start=Array.from(text.slice(0,m.index)).length,end=start+Array.from(m[0]).length;const points=[...new Set([start,end,...spans.flatMap(s=>[s.start,s.end]).filter(p=>p>start&&p<end)])].sort((a,b)=>a-b);for(let i=0;i<points.length-1;i++){const a=points[i],b=points[i+1];const idx=spans.findIndex(s=>s.start<=a&&s.end>=b),s=spans[idx];out.push({text:chars.slice(a,b).join(''),start:a,end:b,position:out.length,label:s?.label||'O',bio:s?(out.at(-1)?.span_group===idx?'I-':'B-')+s.label:'O',span_group:s?idx:null});}}return out;}
function crc32(data){let crc=0xffffffff;for(const b of data){crc^=b;for(let i=0;i<8;i++)crc=(crc>>>1)^((crc&1)?0xedb88320:0);}return (crc^0xffffffff)>>>0;}
function join(parts){const length=parts.reduce((n,p)=>n+p.length,0),out=new Uint8Array(length);let at=0;for(const p of parts){out.set(p,at);at+=p.length;}return out;}
function zip(files){const locals=[],central=[];let offset=0;for(const [name,text]of Object.entries(files)){const filename=enc.encode(name),data=enc.encode(text),crc=crc32(data);const h=new Uint8Array(30),d=new DataView(h.buffer);d.setUint32(0,0x04034b50,true);d.setUint16(4,20,true);d.setUint16(6,0x800,true);d.setUint16(12,33,true);d.setUint32(14,crc,true);d.setUint32(18,data.length,true);d.setUint32(22,data.length,true);d.setUint16(26,filename.length,true);locals.push(h,filename,data);const c=new Uint8Array(46),v=new DataView(c.buffer);v.setUint32(0,0x02014b50,true);v.setUint16(4,20,true);v.setUint16(6,20,true);v.setUint16(8,0x800,true);v.setUint16(14,33,true);v.setUint32(16,crc,true);v.setUint32(20,data.length,true);v.setUint32(24,data.length,true);v.setUint16(28,filename.length,true);v.setUint32(42,offset,true);central.push(c,filename);offset+=h.length+filename.length+data.length;}const size=central.reduce((n,p)=>n+p.length,0),end=new Uint8Array(22),v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,Object.keys(files).length,true);v.setUint16(10,Object.keys(files).length,true);v.setUint32(12,size,true);v.setUint32(16,offset,true);return join([...locals,...central,end]);}
function col(n){let out='';for(n++;n;n=Math.floor((n-1)/26))out=String.fromCharCode(65+(n-1)%26)+out;return out;}
function sheet(rows){return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>'+rows.map((r,i)=>`<row r="${i+1}">${r.map((value,j)=>typeof value==='number'?`<c r="${col(j)}${i+1}" t="n"><v>${value}</v></c>`:`<c r="${col(j)}${i+1}" t="inlineStr"><is><t xml:space="preserve">${xml(protect(value))}</t></is></c>`).join('')}</row>`).join('')+'</sheetData></worksheet>';}
function xlsx(rows,project){const sentences=[['id','text','label','ai_label','manual_label','gold_label','review_status'],...rows.map(r=>[r.id,r.text,r.label,r.ai_label,r.manual_label,r.gold_label,r.review_status])];const spans=[['id','span_text','label','start','end'],...rows.flatMap(r=>r.spans.map(s=>[r.id,s.text,s.label,s.start,s.end]))];const names=['Câu','Cụm đã gán nhãn','Thông tin'];const files={
 '[Content_Types].xml':'<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'+names.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')+'</Types>',
 '_rels/.rels':'<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>',
 'xl/workbook.xml':'<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>'+names.map((n,i)=>`<sheet name="${xml(n)}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')+'</sheets></workbook>',
 'xl/_rels/workbook.xml.rels':'<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+names.map((_,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')+'</Relationships>',
 'xl/worksheets/sheet1.xml':sheet(sentences),'xl/worksheets/sheet2.xml':sheet(spans),'xl/worksheets/sheet3.xml':sheet([['Project',project],['Records',rows.length],['Offsets','Unicode code points; end exclusive']])};return zip(files);}
export function formatExport(raw,fmt,labels=[],project='AnnotaFlow demo'){const rows=raw.map(r=>({...r,spans:(r.spans||[]).map(s=>({...s,text:Array.from(r.text).slice(s.start,s.end).join('')})),tokens:tokenize(r.text,r.spans||[])}));let body,type='application/json';
 if(fmt==='json_sentence')body=json(rows.map(({tokens,spans,...r})=>r));
 else if(fmt==='json_token')body=json(rows);
 else if(fmt==='jsonl')body=rows.map(json).join('\n')+'\n';
 else if(fmt==='conll'||fmt==='conll_full'){body=rows.map(r=>`# id = ${r.id}\n# label = ${r.label}\n`+r.tokens.map(t=>(fmt==='conll'?[t.text,t.bio]:[t.text,t.start,t.end,t.bio,r.label]).join('\t')).join('\n')).join('\n\n');type='text/plain';}
 else if(fmt==='hf_jsonl'){const names=['O',...labels.flatMap(l=>['B-'+l.key,'I-'+l.key]).sort()];body=[json({__meta__:true,project,label_names:names}),...rows.map(r=>json({id:r.id,tokens:r.tokens.map(t=>t.text),ner_tags:r.tokens.map(t=>names.indexOf(t.bio)),bio_tags:r.tokens.map(t=>t.bio),sentence_label:r.label,review_status:r.review_status}))].join('\n')+'\n';}
 else if(fmt==='spacy_json')body=json(rows.map(r=>[r.text,{entities:r.spans.map(s=>[s.start,s.end,s.label]),cats:r.label==='O'?{}:{[r.label]:1}}]));
 else if(fmt==='doccano_jsonl')body=rows.map(r=>json({id:r.id,text:r.text,label:r.spans.map(s=>[s.start,s.end,s.label]),cats:r.label==='O'?[]:[r.label]})).join('\n')+'\n';
 else if(fmt==='label_studio_json')body=json(rows.map(r=>({data:{text:r.text,ref_id:r.id},annotations:[{result:[...r.spans.map(s=>({from_name:'label',to_name:'text',type:'labels',value:{start:s.start,end:s.end,text:s.text,labels:[s.label]}})),{from_name:'sentence',to_name:'text',type:'choices',value:{choices:[r.label]}}]}]})));
 else if(fmt==='json_llm')body=rows.map(r=>json({messages:[{role:'system',content:'Gán nhãn bình luận tiếng Việt và spans; trả JSON.'},{role:'user',content:r.text},{role:'assistant',content:json({label:r.label,is_meaningful:r.is_meaningful??true,spans:r.spans})}],metadata:{id:r.id,review_status:r.review_status}})).join('\n')+'\n';
 else if(fmt==='xml'){body='<?xml version="1.0" encoding="UTF-8"?><corpus project="'+xml(project)+'">'+rows.map(r=>`<sentence id="${r.id}" label="${xml(r.label)}"><text>${xml(r.text)}</text><tokens>${r.tokens.map(t=>`<token start="${t.start}" end="${t.end}" bio="${xml(t.bio)}">${xml(t.text)}</token>`).join('')}</tokens><spans>${r.spans.map(s=>`<span start="${s.start}" end="${s.end}" label="${xml(s.label)}">${xml(s.text)}</span>`).join('')}</spans></sentence>`).join('')+'</corpus>';type='application/xml';}
 else if(fmt==='csv_sentence'){body=csv(rows,['id','text','source','label','ai_label','manual_label','gold_label','review_status','is_meaningful']);type='text/csv';}
 else if(fmt==='csv_token'){body=csv(rows.flatMap(r=>r.tokens.map(t=>({comment_id:r.id,comment_label:r.label,...t}))),['comment_id','comment_label','text','label','bio','position','start','end','span_group']);type='text/csv';}
 else if(fmt==='csv_spans'){body=csv(rows.flatMap(r=>r.spans.map(s=>({comment_id:r.id,comment_text:r.text,comment_label:r.label,span_text:s.text,span_label:s.label,start:s.start,end:s.end}))),['comment_id','comment_text','comment_label','span_text','span_label','start','end']);type='text/csv';}
 else if(fmt==='csv_annotations'){body=csv(rows.flatMap(r=>(r.annotators||[]).map(a=>({comment_id:r.id,text:r.text,annotator:a.user_id,source:'human',label:a.label,assisted:a.assisted,created_at:a.updated_at}))),['comment_id','text','annotator','source','label','assisted','created_at']);type='text/csv';}
 else if(fmt==='xlsx'){body=xlsx(rows,project);type='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';}
 else throw new Error('Unsupported export format');return {body,type};}
